// Admin audit dashboard — displays question-bank integrity snapshot.
// Snapshot file is generated by backend/scripts/generate-audit-snapshot.js
// and committed to frontend/public/audit-snapshot.json.
//
// No backend auth — this is intentionally a public page that shows non-sensitive
// data integrity counts. Useful for transparency + tracking improvements over
// time. The actual audit logic stays server-side; this page just renders the
// pre-computed JSON.
import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { usePageMeta } from '../hooks/usePageMeta'

export default function AdminAudit() {
  const navigate = useNavigate()
  const [snap, setSnap] = useState(null)
  const [err, setErr] = useState(null)
  const [sortBy, setSortBy] = useState('total')
  const [showShared, setShowShared] = useState(false)

  usePageMeta('題庫健檢｜國考知識王', '題庫資料完整性審計報告：題數、incomplete、disputed、重複 ID、選項異常等指標。')

  useEffect(() => {
    fetch('/audit-snapshot.json')
      .then(r => r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`)))
      .then(setSnap)
      .catch(e => setErr(e.message))
  }, [])

  if (err) {
    return (
      <div className="max-w-5xl mx-auto px-4 py-6">
        <div className="bg-red-50 border border-red-200 rounded-2xl p-4 text-sm text-red-700">
          載入快照失敗：{err}
          <br/>
          請先在 backend 跑：<code className="px-1 bg-red-100 rounded">node scripts/generate-audit-snapshot.js</code>
        </div>
      </div>
    )
  }
  if (!snap) return <div className="max-w-5xl mx-auto px-4 py-6 text-gray-400">載入中…</div>

  const { total, exams, shared, generatedAt } = snap
  const rows = showShared ? shared : exams
  const sorted = [...rows].sort((a, b) => {
    if (sortBy === 'name') return a.file.localeCompare(b.file)
    if (sortBy === 'incomplete') return b.incomplete - a.incomplete
    if (sortBy === 'disputed') return b.disputed - a.disputed
    if (sortBy === 'realbugs') return realBugCount(b.issues) - realBugCount(a.issues)
    return b.total - a.total
  })

  function realBugCount(issues) {
    // "Real" bugs (vs structural design like options_lt_4 from 是非題)
    return (issues.missing_answer || 0) + (issues.duplicate_id || 0) +
      (issues.answer_not_in_options || 0) + (issues.pollution || 0)
  }

  const totalRealBugs = realBugCount(total.issues)

  return (
    <div className="max-w-5xl mx-auto px-4 py-6">
      <button
        onClick={() => navigate(-1)}
        className="text-sm text-gray-500 hover:text-medical-blue flex items-center gap-1 mb-3 active:scale-95"
      >
        ← 返回
      </button>
      <h1 className="text-2xl font-bold text-medical-dark mb-1">題庫健檢</h1>
      <p className="text-xs text-gray-400 mb-4">
        快照時間：{new Date(generatedAt).toLocaleString('zh-TW')}
      </p>

      {/* Overall summary cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
        <SummaryCard label="總題數" value={total.totalQ.toLocaleString()} accent="blue" />
        <SummaryCard label="考試種類" value={`${total.exams} + ${total.shared}`} sub="考試 + 共用題庫" accent="indigo" />
        <SummaryCard label="incomplete" value={total.incomplete.toLocaleString()} sub="已排除出題池" accent="gray" />
        <SummaryCard label="disputed" value={total.disputed.toLocaleString()} sub="考選部爭議題" accent="amber" />
      </div>

      {/* Real bug callouts */}
      <div className="bg-white border border-gray-100 rounded-2xl p-4 mb-6">
        <div className="flex items-center justify-between mb-3">
          <h2 className="font-bold text-medical-dark">資料整合性</h2>
          <span className={`text-xs px-2 py-1 rounded-full font-medium ${
            totalRealBugs === 0 ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'
          }`}>
            {totalRealBugs === 0 ? '✓ 無已知 bug' : `${totalRealBugs} 個待修`}
          </span>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs">
          <IssueChip label="缺答案" value={total.issues.missing_answer} bad />
          <IssueChip label="重複 ID" value={total.issues.duplicate_id} bad />
          <IssueChip label="答案不在選項" value={total.issues.answer_not_in_options} bad />
          <IssueChip label="題幹污染" value={total.issues.pollution} bad />
          <IssueChip label="空選項" value={total.issues.empty_options} />
          <IssueChip label="選項超長 (&gt;400ch)" value={total.issues.option_too_long} />
          <IssueChip label="少於 4 選項" value={total.issues.options_lt_4} />
          <IssueChip label="短題幹 (&lt;5ch)" value={total.issues.short_question} />
        </div>
        <p className="text-[10px] text-gray-400 mt-2">
          注：選項超長、少於 4 選項、短題幹多為合理設計（是非題、長段落題），非真實 bug。
        </p>
      </div>

      {/* Per-exam table */}
      <div className="bg-white border border-gray-100 rounded-2xl overflow-hidden">
        <div className="flex items-center justify-between p-3 border-b border-gray-100">
          <div className="flex gap-2">
            <button
              onClick={() => setShowShared(false)}
              className={`text-xs px-3 py-1 rounded-full ${!showShared ? 'bg-medical-blue text-white' : 'bg-gray-100 text-gray-600'}`}
            >考試 ({total.exams})</button>
            <button
              onClick={() => setShowShared(true)}
              className={`text-xs px-3 py-1 rounded-full ${showShared ? 'bg-medical-blue text-white' : 'bg-gray-100 text-gray-600'}`}
            >共用題庫 ({total.shared})</button>
          </div>
          <select
            value={sortBy}
            onChange={e => setSortBy(e.target.value)}
            className="text-xs px-2 py-1 border border-gray-200 rounded-md bg-white"
          >
            <option value="total">題數高→低</option>
            <option value="incomplete">incomplete 高→低</option>
            <option value="disputed">disputed 高→低</option>
            <option value="realbugs">bug 高→低</option>
            <option value="name">名稱</option>
          </select>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead className="bg-gray-50 text-gray-500">
              <tr>
                <th className="text-left p-2 font-medium">考試</th>
                <th className="text-right p-2 font-medium">題數</th>
                <th className="text-right p-2 font-medium">incomplete</th>
                <th className="text-right p-2 font-medium">disputed</th>
                <th className="text-right p-2 font-medium">real bugs</th>
                <th className="text-right p-2 font-medium hidden md:table-cell">年份</th>
              </tr>
            </thead>
            <tbody>
              {sorted.map(e => {
                const bugs = realBugCount(e.issues)
                const years = Object.keys(e.yearCoverage).sort()
                const yearRange = years.length > 0 ? `${years[0]}-${years[years.length - 1]}` : '-'
                return (
                  <tr key={e.file} className="border-t border-gray-50">
                    <td className="p-2 font-mono text-gray-700">{e.file}</td>
                    <td className="p-2 text-right text-gray-600">{e.total.toLocaleString()}</td>
                    <td className="p-2 text-right">
                      {e.incomplete > 0 ? <span className="text-gray-500">{e.incomplete}</span> : <span className="text-green-600">0</span>}
                    </td>
                    <td className="p-2 text-right">
                      {e.disputed > 0 ? <span className="text-amber-600">{e.disputed}</span> : <span className="text-gray-300">0</span>}
                    </td>
                    <td className="p-2 text-right">
                      {bugs > 0 ? <span className="text-red-600 font-medium">{bugs}</span> : <span className="text-green-600">✓</span>}
                    </td>
                    <td className="p-2 text-right text-gray-400 font-mono hidden md:table-cell">{yearRange}</td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      </div>

      <p className="text-[10px] text-gray-400 mt-4">
        快照來源：<code className="px-1 bg-gray-100 rounded">backend/scripts/generate-audit-snapshot.js</code>。
        手動 push 後生效；不會即時更新。
      </p>
    </div>
  )
}

function SummaryCard({ label, value, sub, accent = 'gray' }) {
  const colors = {
    blue: 'border-blue-200 bg-blue-50',
    indigo: 'border-indigo-200 bg-indigo-50',
    gray: 'border-gray-200 bg-gray-50',
    amber: 'border-amber-200 bg-amber-50',
  }
  return (
    <div className={`rounded-2xl border ${colors[accent]} p-3`}>
      <div className="text-xs text-gray-500 mb-1">{label}</div>
      <div className="text-xl font-bold text-medical-dark">{value}</div>
      {sub && <div className="text-[10px] text-gray-400 mt-1">{sub}</div>}
    </div>
  )
}

function IssueChip({ label, value, bad = false }) {
  const v = value || 0
  return (
    <div className={`flex items-center justify-between px-2 py-1 rounded-md ${
      v === 0 ? 'bg-green-50 text-green-700' : (bad ? 'bg-red-50 text-red-700' : 'bg-gray-50 text-gray-600')
    }`}>
      <span dangerouslySetInnerHTML={{ __html: label }} />
      <span className="font-mono font-medium">{v}</span>
    </div>
  )
}
